import React from 'react';

const Footer: React.FC = () => {
  return (
    <footer className='footer'>
      <div className='container'>
        <div className='footer__top'>
          <img src='img/logo-footer.jpg' alt='логотип neoflex' />
          <div className='footer__top-inner'>
            <a href='tel:+74959842513' className='footer__tel'>
              +7 (495) 984 25 13
            </a>
            <a href='mailto:info@neoflex.ru' className='footer__email'>
              info@neoflex.ru
            </a>
          </div>
        </div>
        <div className='footer__mid'>
          <nav aria-label='навигация в подвале' className='footer__nav'></nav>
        </div>
        <div className='footer__bottom'></div>
      </div>
    </footer>
  );
};

export default Footer;
